/**
 * Informes: generación en pantalla + exportación a PDF (jsPDF), Excel
 * (SheetJS) y envío por correo (mailto). Incluye ahora el estado de pago
 * de cada registro de horas (pagado / pendiente de cobro), para que el
 * informe muestre no solo el valor ejecutado sino también lo que queda
 * pendiente de pago (cuentas por cobrar).
 */
let lastReport = null;

// Logo en base64 para el encabezado del PDF (mismo isotipo de la barra superior).
const REPORT_LOGO_B64 = 'data:image/png;base64,';
const REPORT_SIGNATURE_B64 = 'data:image/png;base64,';

function monthLabel(m) {
  if (!m) return '';
  const d = new Date(`${m}-01T12:00:00`);
  return d.toLocaleDateString('es-CO', { month: 'long', year: 'numeric' });
}

// Iniciales automáticas de un nombre (proveedor/empresa) para el número de
// la Cuenta de cobro — ej: "Aguas de la Sabana S.A. E.S.P." → "AGUA".
function invoiceInitials(name, len = 4) {
  const clean = (name || '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-zA-Z]/g, '').toUpperCase();
  return clean.slice(0, len) || 'GEN';
}

// Repuebla #reportProvider según el tipo de informe: "Informe por
// proveedor" solo admite proveedores reales (así lo esperaba ya ese
// informe); "Cuenta de cobro" (migración 0020) admite también empresas sin
// proveedor asignado, tratadas como su propio proveedor de una sola
// empresa. Conserva la selección actual si sigue siendo válida.
function populateReportProviderSelect(scope) {
  const sel = $('reportProvider');
  if (!sel) return;
  const prev = sel.value;
  const options = scope === 'invoice' ? listBillingTargets().map(t => ({ value: billingTargetValue(t), label: t.name }))
    : state.providers.map(p => ({ value: p.id, label: p.name }));
  sel.innerHTML = options.length
    ? options.map(o => `<option value="${o.value}">${o.label}</option>`).join('')
    : '<option value="">(sin proveedores creados)</option>';
  if (options.some(o => o.value === prev)) sel.value = prev;
}

function generateReport() {
  const scopeSel = $('reportScope')?.value || 'monthly';
  // El selector de proveedor se usa tanto para el "Informe por proveedor"
  // como para la "Cuenta de cobro" — se muestra/oculta según el tipo de
  // informe elegido.
  if ($('reportProviderWrap')) $('reportProviderWrap').style.display = (scopeSel === 'provider' || scopeSel === 'invoice') ? 'block' : 'none';
  if (scopeSel === 'provider' || scopeSel === 'invoice') populateReportProviderSelect(scopeSel);
  if (scopeSel === 'invoice') { renderInvoiceReport(); return null; }
  if (scopeSel === 'all') { renderGlobalReport(); return null; }
  if (scopeSel === 'provider') { renderProviderReport(); return null; }
  if (scopeSel === 'invoice') { renderInvoiceReport(); return null; }
  try {
    const c = company(), s = site();
    if (!c || !s) { toast('Selecciona empresa y sede antes de generar el informe.'); return null; }
    const m = $('reportMonth')?.value || selectedMonth(), scope = $('reportScope')?.value || 'monthly';
    const monthly = state.hoursSite.filter(x => x.site_id === s.id && monthOf(x.record_date) === m);
    const all = state.hoursSite.filter(x => x.site_id === s.id);
    const rows = scope === 'global' ? all : monthly;

    const used = rows.reduce((a, x) => a + Number(x.hours), 0);
    const executed = rows.reduce((a, x) => a + Number(x.hours) * Number(x.rate), 0);
    const paidValue = rows.filter(x => x.paid).reduce((a, x) => a + Number(x.hours) * Number(x.rate), 0);
    const owedValue = rows.filter(x => !x.paid).reduce((a, x) => a + Number(x.hours) * Number(x.rate), 0);
    const paidCount = rows.filter(x => x.paid).length, owedCount = rows.length - paidCount;
    const monthValue = monthly.reduce((a, x) => a + Number(x.hours) * Number(x.rate), 0);

    const bag = state.bag, bagRemainingValue = bag.remaining * companyRate(c);
    const ev = state.evidencesSite.filter(x => scope === 'global' || monthOf(x.record_date) === m);
    // Solo las actividades que quedaron asignadas a ESTA sede (Configuración
    // → Sedes y horas → Actividades), no el catálogo global completo — antes
    // el informe mostraba actividades que no tenían nada que ver con la
    // empresa.
    const acts = activitiesForSite(s.id).map((t, i) => {
      const st = taskStatus(s.id, t.id), hrs = scope === 'global' ? taskHours(s.id, t.id) : taskMonthHours(s.id, t.id, m);
      const target = activityTarget(s.id, t.id);
      return { name: t.name, status: st, hours: hrs, target, icon: actIcon(i) };
    });
    const title = scope === 'global' ? 'Informe global consolidado SG-SST' : 'Informe mensual de seguimiento SG-SST';
    const subtitle = scope === 'global'
      ? 'Resumen consolidado de la gestión, actividades, horas y valores de todo el histórico registrado.'
      : 'Resumen de la gestión, actividades, horas y valores correspondientes al periodo.';
    const genDate = new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' });

    const completedCount = acts.filter(a => a.status === 'Completada').length;
    const totalActs = acts.length;
    const avancePct = scope === 'global'
      ? (totalActs ? Math.round(100 * completedCount / totalActs) : null)
      : (bag.total ? Math.min(100, Math.round(100 * bag.used / bag.total)) : null);
    const avanceSub = scope === 'global'
      ? `${completedCount} de ${totalActs} actividad(es) completadas`
      : `${bag.used} h de ${bag.total} h de la bolsa asignada`;
    const carteraOk = owedValue <= 0;

    const finRows = scope === 'global'
      ? [
          ['Horas ejecutadas (total)', `${used} h`, money(executed)],
          ['Valor pagado', '–', money(paidValue)],
          ['VALOR PENDIENTE', '–', money(owedValue)],
        ]
      : [
          ['Horas asignadas', `${bag.total} h`, money(bag.total * companyRate(c))],
          ['Horas ejecutadas', `${used} h`, money(executed)],
          ['Horas disponibles', `${bag.remaining} h`, money(bagRemainingValue)],
          ['Valor pagado', '–', money(paidValue)],
          ['VALOR PENDIENTE', '–', money(owedValue)],
        ];

    const analysisParas = [
      `Durante ${scope === 'global' ? 'el periodo consolidado' : monthLabel(m)} se ${scope === 'global' ? 'han registrado' : 'registraron'} ${used} horas de ejecución${scope === 'monthly' && bag.total ? `, correspondientes al ${avancePct}% de la bolsa mensual asignada` : ''}.`,
      `Actualmente se cuenta con un saldo disponible de ${bag.remaining} horas en la bolsa de ${m}, equivalente a ${money(bagRemainingValue)}, las cuales podrán ser utilizadas para continuar con las actividades programadas.`,
      carteraOk
        ? 'En cuanto al componente financiero, no se registran valores pendientes de pago; la cartera se encuentra al día.'
        : `En cuanto al componente financiero, se encuentra pendiente un valor de ${money(owedValue)}, correspondiente a los servicios ejecutados durante el periodo.`,
    ];

    $('reportBox').innerHTML = `
    <div class="reportTopBar">
      <div class="reportBrand">
        <img src="${REPORT_LOGO_B64}" alt="SST Asesorías y Consultorías">
        <div class="reportBrandText"><h2>${title.toUpperCase()}</h2><p>${subtitle}</p></div>
      </div>
      <div class="reportInfoBox">
        <span class="lbl">Empresa:</span><span class="val">${c.name}</span>
        <span class="lbl">Sede:</span><span class="val">${s.name}</span>
        <span class="lbl">Periodo:</span><span class="val">${monthLabel(m)}</span>
        <span class="lbl">Generado el:</span><span class="val">${genDate}</span>
        <span class="lbl">Responsable:</span><span class="val">Yasbleidis López Rhenals</span>
      </div>
    </div>

    <div class="reportSectionTitle">📊 1. Resumen ejecutivo</div>
    <div class="reportKpiRow">
      <div class="reportKpiCard c-blue"><div class="k-label">Horas ejecutadas</div><div class="k-value">${used} h</div><div class="k-sub">${scope === 'global' ? 'Histórico de la sede' : `De un total de ${bag.total} h asignadas`}</div></div>
      <div class="reportKpiCard c-green"><div class="k-label">Avance del periodo</div><div class="k-value">${avancePct === null ? '—' : avancePct + '%'}</div><div class="k-sub">${avanceSub}</div></div>
      <div class="reportKpiCard c-blue"><div class="k-label">Valor ejecutado</div><div class="k-value">${money(executed)}</div><div class="k-sub">Valor correspondiente a las horas ejecutadas</div></div>
      <div class="reportKpiCard c-orange"><div class="k-label">Valor pendiente de pago</div><div class="k-value">${money(owedValue)}</div><div class="k-sub">${owedCount} registro(s) sin pagar</div></div>
      <div class="reportKpiCard c-purple"><div class="k-label">Saldo disponible</div><div class="k-value">${bag.remaining} h</div><div class="k-sub">Equivalente a ${money(bagRemainingValue)} en horas pendientes por ejecutar</div></div>
    </div>

    <div class="reportGrid2" style="margin-top:22px">
      <div>
        <div class="reportSectionTitle">📋 2. Resumen financiero</div>
        <div class="tablewrap"><table><thead><tr><th>Concepto</th><th>Horas</th><th>Valor</th></tr></thead><tbody>
          ${finRows.map(r => `<tr${r[0] === 'VALOR PENDIENTE' ? ' style="background:#fdf1ef"' : ''}><td${r[0] === 'VALOR PENDIENTE' ? ' style="color:var(--danger);font-weight:800"' : ''}>${r[0]}</td><td>${r[1]}</td><td${r[0] === 'VALOR PENDIENTE' ? ' style="color:var(--danger);font-weight:800"' : ''}>${r[2]}</td></tr>`).join('')}
        </tbody></table></div>
      </div>
      <div class="reportMiniCard">
        <div class="icon">${carteraOk ? '✅' : '🧾'}</div>
        <div style="font-size:11px;color:var(--muted);text-transform:uppercase;font-weight:800;margin-top:6px">Estado de cartera</div>
        <div class="status ${carteraOk ? 'ok' : 'bad'}">${carteraOk ? 'Al día' : 'Pendiente de pago'}</div>
        <div class="amt" style="color:${carteraOk ? '#21714f' : 'var(--danger)'}">${money(owedValue)}</div>
        <div class="amtsub">Registros pendientes: <b>${owedCount}</b></div>
      </div>
    </div>

    <div class="reportSectionTitle">🕐 3. Bolsa de horas de ${monthLabel(m)}</div>
    <div class="reportStatCard">
      <div class="reportStatRow"><span class="rs-label">Bolsa del mes (total)</span><span class="rs-value">${bag.total} h</span></div>
      <div class="reportStatRow"><span class="rs-label">Asignadas ${bag.assigned} · Saldo anterior ${bag.carry} · Adicionales ${bag.additional}</span><span class="rs-value"></span></div>
      <div class="reportStatRow"><span class="rs-label">Horas ejecutadas en ${monthLabel(m)}</span><span class="rs-value">${bag.used} h</span></div>
      <div class="reportStatRow"><span class="rs-label">Saldo disponible (valorizado)</span><span class="rs-value">${bag.remaining} h · ${money(bagRemainingValue)}</span></div>
    </div>

    <div class="reportSectionTitle">📋 4. Actividades desarrolladas</div>
    <div class="tablewrap"><table><thead><tr><th>Actividad</th><th>Estado</th><th>Horas</th><th>Avance</th><th>Observaciones</th></tr></thead><tbody>
      ${acts.map(a => `<tr><td>${a.icon} ${a.name}</td><td><span class="badge ${a.status === 'Completada' ? 'done' : a.status === 'En proceso' ? 'progress' : 'pending'}">${a.status}</span></td><td>${a.hours} h</td><td>${a.target ? `<div class="reportProgressMini"><div class="bar"><div class="fill" style="width:${Math.min(100, Math.round(100 * a.hours / a.target))}%"></div></div><span class="pct">${Math.min(100, Math.round(100 * a.hours / a.target))}%</span></div>` : '<span class="small">Sin meta definida</span>'}</td><td class="small">${a.status === 'Completada' ? 'Actividad finalizada.' : a.status === 'En proceso' ? 'En desarrollo durante el periodo.' : 'Programada para el próximo periodo.'}</td></tr>`).join('')}
    </tbody></table></div>

    <div class="reportGrid2" style="margin-top:22px">
      <div>
        <div class="reportSectionTitle">📎 5. Evidencias del periodo (${ev.length})</div>
        ${ev.length ? `<div class="tablewrap"><table><thead><tr><th>Actividad</th><th>Fecha</th><th>Enlace</th></tr></thead><tbody>${ev.slice(0, 12).map(x => `<tr><td>${taskName(x.activity_id)}${x.description ? ' — ' + x.description : ''}</td><td>${x.record_date}</td><td>${x.link ? `<a class="link" href="${safeUrl(x.link)}" target="_blank">Ver evidencia ↗</a>` : (x.storage_path ? `<a class="link" href="#" onclick="openEvidenceFile('${x.id}');return false">📄 ${x.file_name || 'archivo'}</a>` : '—')}</td></tr>`).join('')}</tbody></table></div>${ev.length > 12 ? `<p class="small">y ${ev.length - 12} evidencia(s) más…</p>` : ''}` : '<p class="small">No hay evidencias registradas en este periodo.</p>'}
      </div>
      <div>
        <div class="reportSectionTitle">💬 6. Análisis y observaciones</div>
        <div class="reportAnalysis">${analysisParas.map(p => `<p>${p}</p>`).join('')}</div>
      </div>
    </div>

    <div class="reportSectionTitle" style="margin-top:22px">🧾 Detalle de horas ejecutadas</div>
    <div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Actividad</th><th>Horas</th><th>Tarifa</th><th>Valor</th><th>Pago</th></tr></thead><tbody>
      ${rows.length ? [...rows].sort((a, b) => b.record_date.localeCompare(a.record_date)).map(x => `<tr><td>${x.record_date}</td><td>${taskName(x.activity_id)}</td><td>${x.hours}</td><td>${money(x.rate)}</td><td>${money(x.hours * x.rate)}</td><td><span class="badge ${x.paid ? 'paid' : 'unpaid'}">${x.paid ? '✓ Pagado' : '⏳ Pendiente'}</span></td></tr>`).join('') : '<tr><td colspan="6" class="empty">Sin registros en este periodo.</td></tr>'}
    </tbody></table></div>

    <div class="reportSectionTitle" style="margin-top:22px">✍️ 7. Elaborado por</div>
    <div class="reportSignatureBlock"><img src="${REPORT_SIGNATURE_B64}" alt="Yasbleidis López Rhenals · SST Asesorías y Consultorías"></div>
    `;
    toast('Informe generado');
    lastReport = { c, s, m, scope, used, executed, paidValue, owedValue, paidCount, owedCount, monthValue, bagRemainingValue, ev, bag, acts, rows, title, subtitle, genDate, avancePct, avanceSub, carteraOk, analysisParas, finRows };
    return lastReport;
  } catch (err) {
    console.error('Error generando el informe:', err);
    toast('No se pudo generar el informe: ' + (err?.message || err));
    return null;
  }
}

// Informe general: junta TODAS las empresas y sedes en un solo documento
// (avance actual + cartera consolidada), en vez del histórico de una sola
// sede. Usa el mismo cálculo que el panel "Resumen general" del Dashboard
// (computeGlobalOverview, definido en app.js) para que ambos coincidan
// siempre. Es async porque tiene que consultar la bolsa de cada sede.
async function renderGlobalReport() {
  const box = $('reportBox');
  if (box) box.innerHTML = '<p class="empty">Generando informe general, un momento…</p>';
  toast('Generando informe general…');
  try {
    const m = $('reportMonth')?.value || selectedMonth();
    const { rows, totals } = await computeGlobalOverview(m);
    const title = 'Informe general consolidado SG-SST';
    const subtitle = 'Avance actual y cartera de todas las empresas y sedes.';
    const genDate = new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' });

    if (!rows.length) {
      if (box) box.innerHTML = '<p class="empty">Todavía no hay empresas con sedes registradas.</p>';
      lastReport = null;
      return null;
    }

    const finRows = [
      ['Horas asignadas', `${totals.assigned} h`, ''],
      ['Horas ejecutadas', `${totals.used} h`, ''],
      ['Horas disponibles', `${totals.remaining} h`, ''],
      ['Valor pagado', '–', money(totals.paidValue)],
      ['VALOR PENDIENTE', '–', money(totals.owedValue)],
    ];

    if (box) box.innerHTML = `
    <div class="reportTopBar">
      <div class="reportBrand">
        <img src="${REPORT_LOGO_B64}" alt="SST Asesorías y Consultorías">
        <div class="reportBrandText"><h2>${title.toUpperCase()}</h2><p>${subtitle}</p></div>
      </div>
      <div class="reportInfoBox">
        <span class="lbl">Alcance:</span><span class="val">Todas las empresas y sedes</span>
        <span class="lbl">Periodo:</span><span class="val">${monthLabel(m)}</span>
        <span class="lbl">Generado el:</span><span class="val">${genDate}</span>
        <span class="lbl">Responsable:</span><span class="val">Yasbleidis López Rhenals</span>
      </div>
    </div>

    <div class="reportSectionTitle">📊 1. Resumen ejecutivo</div>
    <div class="reportKpiRow">
      <div class="reportKpiCard c-blue"><div class="k-label">Empresas activas</div><div class="k-value">${totals.companiesCount}</div><div class="k-sub">${totals.sitesCount} sede(s) en total</div></div>
      <div class="reportKpiCard c-blue"><div class="k-label">Horas ejecutadas</div><div class="k-value">${totals.used} h</div><div class="k-sub">De un total de ${totals.assigned} h asignadas</div></div>
      <div class="reportKpiCard c-green"><div class="k-label">Avance global</div><div class="k-value">${totals.avancePct === null ? '—' : totals.avancePct + '%'}</div><div class="k-sub">${totals.used} h de ${totals.assigned} h</div></div>
      <div class="reportKpiCard c-orange"><div class="k-label">Valor pendiente de pago</div><div class="k-value">${money(totals.owedValue)}</div><div class="k-sub">Cartera consolidada</div></div>
      <div class="reportKpiCard c-purple"><div class="k-label">Horas disponibles</div><div class="k-value">${totals.remaining} h</div><div class="k-sub">Saldo consolidado de todas las bolsas</div></div>
    </div>

    <div class="reportSectionTitle" style="margin-top:22px">📋 2. Resumen financiero consolidado</div>
    <div class="tablewrap"><table><thead><tr><th>Concepto</th><th>Horas</th><th>Valor</th></tr></thead><tbody>
      ${finRows.map(r => `<tr${r[0] === 'VALOR PENDIENTE' ? ' style="background:#fdf1ef"' : ''}><td${r[0] === 'VALOR PENDIENTE' ? ' style="color:var(--danger);font-weight:800"' : ''}>${r[0]}</td><td>${r[1]}</td><td${r[0] === 'VALOR PENDIENTE' ? ' style="color:var(--danger);font-weight:800"' : ''}>${r[2]}</td></tr>`).join('')}
    </tbody></table></div>

    <div class="reportSectionTitle" style="margin-top:22px">🏢 3. Avance actual por empresa y sede</div>
    <div class="tablewrap"><table><thead><tr><th>Empresa</th><th>Sede</th><th>Asignadas</th><th>Usadas</th><th>Disponibles</th><th>Avance</th><th>Cartera</th></tr></thead><tbody>
      ${rows.map(r => `<tr><td>${r.companyName}</td><td>${r.siteName}</td><td>${r.assigned} h</td><td>${r.used} h</td><td>${r.remaining} h</td><td>${r.avancePct === null ? '—' : r.avancePct + '%'}</td><td>${r.owedValue > 0 ? `<span class="badge unpaid">${money(r.owedValue)}</span>` : '<span class="badge paid">Al día</span>'}</td></tr>`).join('')}
      <tr style="font-weight:800;background:#f4f7fa"><td colspan="2">TOTAL</td><td>${totals.assigned} h</td><td>${totals.used} h</td><td>${totals.remaining} h</td><td>${totals.avancePct === null ? '—' : totals.avancePct + '%'}</td><td>${money(totals.owedValue)}</td></tr>
    </tbody></table></div>

    <div class="reportGrid2" style="margin-top:22px">
      <div>
        <div class="reportSectionTitle">✍️ Elaborado por</div>
        <div class="reportSignatureBlock"><img src="${REPORT_SIGNATURE_B64}" alt="Yasbleidis López Rhenals · SST Asesorías y Consultorías"></div>
      </div>
    </div>
    `;
    toast('Informe general generado');
    lastReport = { scope: 'all', m, rows, totals, title, subtitle, genDate };
    return lastReport;
  } catch (err) {
    console.error('Error generando el informe general:', err);
    toast('No se pudo generar el informe general: ' + (err?.message || err));
    if (box) box.innerHTML = '<p class="empty">No se pudo generar el informe general.</p>';
    return null;
  }
}

// Informe por proveedor: igual que el informe general, pero solo con las
// empresas asociadas a UN proveedor (ej. ARL Positiva). Reutiliza
// computeGlobalOverview con un filtro por company.provider_id, para no
// duplicar el cálculo de bolsas/cartera.
async function renderProviderReport() {
  const box = $('reportBox');
  if (!state.providers.length) {
    if (box) box.innerHTML = '<p class="empty">Todavía no hay proveedores creados. Corre la migración de proveedores en Supabase y recarga la página.</p>';
    lastReport = null;
    return null;
  }
  const providerId = $('reportProvider')?.value || '';
  if (!providerId) {
    if (box) box.innerHTML = '<p class="empty">Selecciona un proveedor para generar su informe consolidado.</p>';
    lastReport = null;
    return null;
  }
  const provider = state.providers.find(p => p.id === providerId);
  const providerName = provider?.name || 'Proveedor';
  if (box) box.innerHTML = '<p class="empty">Generando informe del proveedor, un momento…</p>';
  toast('Generando informe del proveedor…');
  try {
    const m = $('reportMonth')?.value || selectedMonth();
    const { rows, totals } = await computeGlobalOverview(m, c => c.provider_id === providerId);
    const title = `Informe consolidado · ${providerName}`;
    const subtitle = `Avance actual y cartera de las empresas asociadas a ${providerName}.`;
    const genDate = new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' });

    if (!rows.length) {
      if (box) box.innerHTML = `<p class="empty">Todavía no hay empresas asignadas al proveedor "${providerName}". Asígnalas desde Configuración → Empresas.</p>`;
      lastReport = null;
      return null;
    }

    const finRows = [
      ['Horas asignadas', `${totals.assigned} h`, ''],
      ['Horas ejecutadas', `${totals.used} h`, ''],
      ['Horas disponibles', `${totals.remaining} h`, ''],
      ['Valor pagado', '–', money(totals.paidValue)],
      ['VALOR PENDIENTE', '–', money(totals.owedValue)],
    ];

    if (box) box.innerHTML = `
    <div class="reportTopBar">
      <div class="reportBrand">
        <img src="${REPORT_LOGO_B64}" alt="SST Asesorías y Consultorías">
        <div class="reportBrandText"><h2>${title.toUpperCase()}</h2><p>${subtitle}</p></div>
      </div>
      <div class="reportInfoBox">
        <span class="lbl">Proveedor:</span><span class="val">${providerName}</span>
        <span class="lbl">Periodo:</span><span class="val">${monthLabel(m)}</span>
        <span class="lbl">Generado el:</span><span class="val">${genDate}</span>
        <span class="lbl">Responsable:</span><span class="val">Yasbleidis López Rhenals</span>
      </div>
    </div>

    <div class="reportSectionTitle">📊 1. Resumen ejecutivo</div>
    <div class="reportKpiRow">
      <div class="reportKpiCard c-blue"><div class="k-label">Empresas del proveedor</div><div class="k-value">${totals.companiesCount}</div><div class="k-sub">${totals.sitesCount} sede(s) en total</div></div>
      <div class="reportKpiCard c-blue"><div class="k-label">Horas ejecutadas</div><div class="k-value">${totals.used} h</div><div class="k-sub">De un total de ${totals.assigned} h asignadas</div></div>
      <div class="reportKpiCard c-green"><div class="k-label">Avance</div><div class="k-value">${totals.avancePct === null ? '—' : totals.avancePct + '%'}</div><div class="k-sub">${totals.used} h de ${totals.assigned} h</div></div>
      <div class="reportKpiCard c-orange"><div class="k-label">Valor pendiente de pago</div><div class="k-value">${money(totals.owedValue)}</div><div class="k-sub">Cartera consolidada del proveedor</div></div>
      <div class="reportKpiCard c-purple"><div class="k-label">Horas disponibles</div><div class="k-value">${totals.remaining} h</div><div class="k-sub">Saldo consolidado de todas las bolsas</div></div>
    </div>

    <div class="reportSectionTitle" style="margin-top:22px">📋 2. Resumen financiero consolidado</div>
    <div class="tablewrap"><table><thead><tr><th>Concepto</th><th>Horas</th><th>Valor</th></tr></thead><tbody>
      ${finRows.map(r => `<tr${r[0] === 'VALOR PENDIENTE' ? ' style="background:#fdf1ef"' : ''}><td${r[0] === 'VALOR PENDIENTE' ? ' style="color:var(--danger);font-weight:800"' : ''}>${r[0]}</td><td>${r[1]}</td><td${r[0] === 'VALOR PENDIENTE' ? ' style="color:var(--danger);font-weight:800"' : ''}>${r[2]}</td></tr>`).join('')}
    </tbody></table></div>

    <div class="reportSectionTitle" style="margin-top:22px">🏢 3. Empresas y sedes de ${providerName}</div>
    <div class="tablewrap"><table><thead><tr><th>Empresa</th><th>Sede</th><th>Asignadas</th><th>Usadas</th><th>Disponibles</th><th>Avance</th><th>Cartera</th></tr></thead><tbody>
      ${rows.map(r => `<tr><td>${r.companyName}</td><td>${r.siteName}</td><td>${r.assigned} h</td><td>${r.used} h</td><td>${r.remaining} h</td><td>${r.avancePct === null ? '—' : r.avancePct + '%'}</td><td>${r.owedValue > 0 ? `<span class="badge unpaid">${money(r.owedValue)}</span>` : '<span class="badge paid">Al día</span>'}</td></tr>`).join('')}
      <tr style="font-weight:800;background:#f4f7fa"><td colspan="2">TOTAL</td><td>${totals.assigned} h</td><td>${totals.used} h</td><td>${totals.remaining} h</td><td>${totals.avancePct === null ? '—' : totals.avancePct + '%'}</td><td>${money(totals.owedValue)}</td></tr>
    </tbody></table></div>

    <div class="reportSectionTitle" style="margin-top:22px">✍️ Elaborado por</div>
    <div class="reportSignatureBlock"><img src="${REPORT_SIGNATURE_B64}" alt="Yasbleidis López Rhenals · SST Asesorías y Consultorías"></div>
    `;
    toast('Informe del proveedor generado');
    lastReport = { scope: 'provider', providerId, providerName, m, rows, totals, title, subtitle, genDate };
    return lastReport;
  } catch (err) {
    console.error('Error generando el informe del proveedor:', err);
    toast('No se pudo generar el informe del proveedor: ' + (err?.message || err));
    if (box) box.innerHTML = '<p class="empty">No se pudo generar el informe del proveedor.</p>';
    return null;
  }
}

// Cuenta de cobro: el documento formal que Yasbleidis le presenta a un
// proveedor para que le paguen, con el detalle de cada actividad ejecutada
// (hour_records) y cada gasto de desplazamiento (expenses) durante un mes,
// en las empresas de ese proveedor. Antes se armaba a mano en Excel — el
// encabezado se llena solo con los datos de facturación del proveedor
// (Configuración → Proveedores) y los datos fijos de Yasbleidis
// (Configuración → Mis datos).
// ---------------------------------------------------------------------------
// Cuenta de cobro: se calcula directamente por RANGO DE FECHA LIBRE sobre
// hour_records/expenses (el mismo mes elegido en "Periodo de referencia"
// arriba), sin depender de ningún cierre previo — se puede regenerar
// cuantas veces se quiera, de cualquier mes, incluso después de corregir
// horas ya cargadas. El selector de proveedor admite también empresas sin
// proveedor asignado (su "proveedor" es ella misma — ver
// listBillingTargets() en app.js).
// ---------------------------------------------------------------------------

async function renderInvoiceReport() {
  const box = $('reportBox');
  const targets = listBillingTargets();
  if (!targets.length) {
    if (box) box.innerHTML = '<p class="empty">Todavía no hay proveedores ni empresas para facturar. Ve a Configuración → Proveedores/Empresas.</p>';
    lastReport = null;
    return null;
  }
  const targetValue = $('reportProvider')?.value || '';
  const target = parseBillingTargetValue(targetValue);
  if (!target) {
    if (box) box.innerHTML = '<p class="empty">Selecciona un proveedor (o empresa) para generar su cuenta de cobro.</p>';
    lastReport = null;
    return null;
  }
  const m = $('reportMonth')?.value || selectedMonth();
  if (!m) {
    if (box) box.innerHTML = '<p class="empty">Selecciona el mes a facturar en "Periodo de referencia".</p>';
    lastReport = null;
    return null;
  }
  const dateFrom = `${m}-01`;
  const lastDay = new Date(Number(m.slice(0, 4)), Number(m.slice(5, 7)), 0).getDate();
  const dateTo = `${m}-${String(lastDay).padStart(2, '0')}`;
  const period = { date_from: dateFrom, date_to: dateTo };

  const provider = target.type === 'provider' ? (state.providers.find(p => p.id === target.id) || {}) : {};
  const providerName = target.type === 'provider'
    ? (provider.name || 'Proveedor')
    : (state.companies.find(c => c.id === target.id)?.name || 'Proveedor');

  if (box) box.innerHTML = '<p class="empty">Generando cuenta de cobro, un momento…</p>';
  toast('Generando cuenta de cobro…');
  try {
    const targetCompanyIds = new Set(companiesForBillingTarget(target).map(c => c.id));
    const companyIds = Array.from(targetCompanyIds);
    let actRows = [];
    if (companyIds.length) {
      const { data: hrs } = await sb.from('hour_records').select('*').in('company_id', companyIds).gte('record_date', period.date_from).lte('record_date', period.date_to);
      actRows = (hrs || []).sort((a, b) => a.record_date.localeCompare(b.record_date));
    }
    // Viáticos (migración 0012): por el mismo rango de fechas del mes
    // facturado.
    let expRows = [];
    try {
      const { data: exps } = await sb.from('expenses').select('*').gte('record_date', period.date_from).lte('record_date', period.date_to);
      expRows = (exps || []).filter(x => targetCompanyIds.has(x.company_id)).sort((a, b) => a.record_date.localeCompare(b.record_date));
    } catch (e) { expRows = []; }

    const companyName = id => state.companies.find(c => c.id === id)?.name || '—';
    // Igual que antes: la cuenta de cobro siempre muestra la tarifa
    // REAL/actual (Configuración → Proveedores/Tarifas) al momento de
    // generarla, sin importar la tarifa congelada en cada hour_records.
    const currentRateFor = companyId => companyRate(state.companies.find(c => c.id === companyId));

    const genDate = new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' });
    const actTotal = actRows.reduce((a, x) => a + Number(x.hours) * currentRateFor(x.company_id), 0);
    const expTotal = expRows.reduce((a, x) => a + Number(x.amount), 0);
    const grandTotal = actTotal + expTotal;
    const adv = state.advisorProfile || {};
    const periodLabel = `${period.date_from} a ${period.date_to}`;

    // Solo se muestran los campos que realmente tienen dato cargado — un
    // documento formal no debe mostrar guiones ni inventar información que
    // todavía no se ha registrado en Configuración.
    const infoRow = (label, value) => value ? `<span class="lbl">${label}:</span><span class="val">${value}</span>` : '';
    const prestadorRows = [
      ['Nombre', 'Yasbleidis López Rhenals'],
      ['Cédula', adv.cedula],
      ['Profesión', adv.profesion],
      ['Registro profesional', adv.registro_profesional],
      ['Licencia SST', adv.licencia_sst],
      ['Dirección', adv.direccion],
      ['Ciudad', [adv.ciudad, adv.departamento].filter(Boolean).join(' · ')],
      ['Teléfono / Celular', [adv.telefono, adv.celular].filter(Boolean).join(' / ')],
      ['Email', adv.email],
      ['Información tributaria', adv.regimen_iva],
      ['Actividad económica', adv.actividad_economica],
    ].map(([l, v]) => infoRow(l, v)).filter(Boolean).join('');

    // Para una empresa sin proveedor (pseudo-proveedor = ella misma) no hay
    // fila en "providers" con NIT/gerente/etc. — se muestra solo lo que
    // realmente existe (el nombre de la empresa), igual que para cualquier
    // otro dato sin cargar.
    const clienteRows = [
      ['Razón social', providerName],
      ['NIT', provider.nit],
      ['Contacto', provider.gerente],
      ['Dirección', provider.direccion],
      ['Ciudad', provider.ciudad],
      ['Teléfono', provider.telefono],
      ['Radicación', provider.email_radicacion],
    ].map(([l, v]) => infoRow(l, v)).filter(Boolean).join('');

    const pagoRows = [
      ['Banco', adv.banco],
      ['Número de cuenta', adv.cuenta_bancaria],
      ['Nequi', adv.nequi],
      ['Llave Bre-B (Bancolombia)', adv.llave_bre_b],
    ].map(([l, v]) => infoRow(l, v)).filter(Boolean).join('');

    // Número de la cuenta de cobro: PROVEEDOR-EMPRESA-FECHA-CONSECUTIVO.
    // El consecutivo es global (migración 0017). El "period" es el mes
    // facturado (YYYY-MM) — es estable (regenerar la cuenta de cobro del
    // mismo mes siempre da el mismo número) y funciona igual para
    // proveedores reales y para empresas sin proveedor (en ese caso se
    // manda provider_id = null, cosa que la función ya soportaba desde la
    // migración 0017).
    const billedCompanyNames = Array.from(new Set([...actRows, ...expRows].map(x => companyName(x.company_id)).filter(Boolean)));
    const empresaCode = billedCompanyNames.length === 0 ? 'GEN'
      : billedCompanyNames.length === 1 ? invoiceInitials(billedCompanyNames[0])
      : billedCompanyNames.length === 2 ? billedCompanyNames.map(n => invoiceInitials(n, 3)).join('+')
      : 'VARIAS';
    const invoiceDateStr = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    const invoiceCodePrefix = `${invoiceInitials(providerName)}-${empresaCode}-${invoiceDateStr}`;
    let invoiceNumber = null;
    try {
      const { data: numData, error: numErr } = await sb.rpc('get_or_create_invoice_number', {
        p_provider_id: target.type === 'provider' ? target.id : null, p_period: m, p_code_prefix: invoiceCodePrefix,
      });
      if (!numErr && numData) invoiceNumber = numData;
    } catch (e) { invoiceNumber = null; }

    if (box) box.innerHTML = `
    <div class="invoiceHeader">
      <img src="${REPORT_LOGO_B64}" alt="SST Asesorías y Consultorías" class="invoiceLogo">
      <div class="invoiceHeaderMeta">
        <span class="invoiceNumber">No. ${invoiceNumber || '[PENDIENTE]'}</span>
        <span class="invoiceMetaLine">Periodo: ${periodLabel}</span>
        <span class="invoiceMetaLine">Fecha de generación: ${genDate}</span>
      </div>
    </div>
    <h1 class="invoiceTitle">Cuenta de cobro</h1>

    <div class="reportGrid2" style="margin-bottom:8px">
      <div>
        <div class="reportSectionTitle" style="margin-top:0">Datos del prestador</div>
        <div class="reportInfoBox" style="grid-template-columns:auto 1fr">${prestadorRows}</div>
      </div>
      <div>
        <div class="reportSectionTitle" style="margin-top:0">Datos del cliente</div>
        <div class="reportInfoBox" style="grid-template-columns:auto 1fr">${clienteRows}</div>
      </div>
    </div>

    <div class="reportSectionTitle">Concepto del servicio</div>
    <p class="invoiceConcept">Relación de actividades de Seguridad y Salud en el Trabajo (SG-SST) ejecutadas para ${providerName}, correspondientes al periodo ${periodLabel}.</p>

    <div class="reportSectionTitle" style="margin-top:22px">Detalle — Actividades realizadas</div>
    <div class="tablewrap"><table><thead><tr><th>No.</th><th>Fecha</th><th>Empresa</th><th>Descripción</th><th>Cantidad</th><th>Valor unitario</th><th>Valor total</th></tr></thead><tbody>
      ${actRows.length ? actRows.map((x, i) => { const r = currentRateFor(x.company_id); return `<tr><td>${i + 1}</td><td>${x.record_date}</td><td>${companyName(x.company_id)}</td><td>${taskName(x.activity_id)}${x.notes ? ' · ' + x.notes : ''}</td><td>${x.hours} h</td><td>${money(r)}</td><td>${money(x.hours * r)}</td></tr>`; }).join('') : '<tr><td colspan="7" class="empty">Sin actividades facturadas en este cierre.</td></tr>'}
      <tr style="font-weight:800;background:#f4f7fa"><td colspan="6">Subtotal actividades</td><td>${money(actTotal)}</td></tr>
    </tbody></table></div>

    ${expRows.length ? `
    <div class="reportSectionTitle" style="margin-top:22px">Detalle — Desplazamiento y gastos de representación</div>
    <div class="tablewrap"><table><thead><tr><th>No.</th><th>Fecha</th><th>Empresa</th><th>Descripción</th><th>Valor total</th></tr></thead><tbody>
      ${expRows.map((x, i) => `<tr><td>${i + 1}</td><td>${x.record_date}</td><td>${companyName(x.company_id)}</td><td>${x.concept}</td><td>${money(x.amount)}</td></tr>`).join('')}
      <tr style="font-weight:800;background:#f4f7fa"><td colspan="4">Subtotal desplazamiento</td><td>${money(expTotal)}</td></tr>
    </tbody></table></div>` : ''}

    <div class="invoiceTotalBand">
      <span>Total a pagar</span>
      <span class="invoiceTotalValue">${money(grandTotal)}</span>
    </div>
    <p class="small" style="margin-top:10px"><b>Valor en letras:</b> ${numeroALetras(grandTotal)}</p>

    ${pagoRows ? `
    <div class="reportSectionTitle" style="margin-top:26px">Forma de pago</div>
    <div class="reportInfoBox" style="grid-template-columns:auto 1fr">${pagoRows}</div>` : ''}

    <div class="reportSectionTitle" style="margin-top:26px">Observaciones</div>
    <p class="small" style="line-height:1.7">
      1. Soy persona natural y cumplo con todos los requisitos para pertenecer al ${adv.regimen_iva || 'Régimen Simplificado'} y me encuentro debidamente inscrito(a) en el RUT.<br>
      2. Me encuentro dentro de las situaciones contempladas en el artículo 499 del Estatuto Tributario.<br>
      3. En constancia y de conformidad con las normas tributarias, no estoy en la obligación de expedir factura y el presente documento se ajusta a las prescripciones legales en esta materia.<br>
      4. Declaro que la información aquí consignada es correcta y se ajusta a las disposiciones legales.
    </p>

    <div class="reportGrid2" style="margin-top:30px">
      <div>
        <div class="reportSectionTitle" style="margin:0 0 8px">Firma</div>
        <div class="reportSignatureBlock"><img src="${REPORT_SIGNATURE_B64}" alt="Yasbleidis López Rhenals"></div>
        <p class="invoiceSignerName">Yasbleidis López Rhenals</p>
        <p class="small" style="text-align:center">${[adv.profesion, adv.registro_profesional ? 'Reg. ' + adv.registro_profesional : ''].filter(Boolean).join(' · ') || 'Prestadora del servicio'}</p>
        <p class="small" style="text-align:center">C.C. ${adv.cedula || '________________'}</p>
      </div>
      <div>
        <div class="reportSectionTitle" style="margin:0 0 8px">Recibido por</div>
        <p class="small" style="margin:44px 0 4px;border-top:1px solid var(--line);padding-top:6px">${provider.gerente || '_______________________________'}</p>
        <p class="small">${providerName}</p>
        <p class="small">Fecha: ____ / ____ / ______</p>
      </div>
    </div>

    <div class="invoiceFooter">
      <span>SST Asesorías y Consultorías</span>
      <span>${[adv.email, adv.telefono || adv.celular].filter(Boolean).join(' · ')}</span>
    </div>
    `;
    toast('Cuenta de cobro generada');
    lastReport = {
      scope: 'invoice', targetValue, m, providerName, periodLabel,
      actRows, expRows, actTotal, expTotal, grandTotal, genDate, invoiceNumber,
      title: `Cuenta de cobro · ${providerName}`,
    };
    return lastReport;
  } catch (err) {
    console.error('Error generando la cuenta de cobro:', err);
    toast('No se pudo generar la cuenta de cobro: ' + (err?.message || err));
    if (box) box.innerHTML = '<p class="empty">No se pudo generar la cuenta de cobro.</p>';
    return null;
  }
}

// Los botones de Exportar/Correo confían en "lastReport" (ya generado por el
// último cambio de filtro/scope, que dispara generateReport() automático).
// Si por alguna carrera async lastReport todavía no está listo para el
// informe general (recién se cambió a "todas las empresas" y las consultas
// no han vuelto), se espera aquí en vez de fallar en silencio.
async function ensureReport() {
  const scope = $('reportScope')?.value || 'monthly';
  if (scope === 'all') return (lastReport && lastReport.scope === 'all') ? lastReport : await renderGlobalReport();
  if (scope === 'provider') {
    const providerId = $('reportProvider')?.value || '';
    return (lastReport && lastReport.scope === 'provider' && lastReport.providerId === providerId) ? lastReport : await renderProviderReport();
  }
  if (scope === 'invoice') {
    const targetValue = $('reportProvider')?.value || '', m = $('reportMonth')?.value || selectedMonth();
    return (lastReport && lastReport.scope === 'invoice' && lastReport.targetValue === targetValue && lastReport.m === m) ? lastReport : await renderInvoiceReport();
  }
  return (lastReport && (lastReport.scope === 'monthly' || lastReport.scope === 'global')) ? lastReport : generateReport();
}

async function prepareEmail() {
  const r = await ensureReport();
  if (!r) return;
  if (r.scope === 'all') {
    const subject = encodeURIComponent(`Informe general SG-SST – Todas las empresas – ${r.m}`);
    const body = encodeURIComponent(
      `Cordial saludo,\n\n` +
      `Compartimos el informe general consolidado de seguimiento para todas las empresas y sedes.\n\n` +
      `Horas ejecutadas: ${r.totals.used} h de ${r.totals.assigned} h asignadas\n` +
      `Avance global: ${r.totals.avancePct === null ? '—' : r.totals.avancePct + '%'}\n` +
      `Valor pagado: ${money(r.totals.paidValue)}\n` +
      `Valor pendiente por cobrar: ${money(r.totals.owedValue)}\n` +
      `Saldo disponible consolidado: ${r.totals.remaining} h\n\n` +
      `Adjunto el informe completo en PDF/Word exportado desde la plataforma.\n\n` +
      `Cordialmente,\nYasbleidis López Rhenals`
    );
    window.location.href = `mailto:?subject=${subject}&body=${body}`;
    return;
  }
  if (r.scope === 'provider') {
    const subject = encodeURIComponent(`Informe consolidado SG-SST – ${r.providerName} – ${r.m}`);
    const body = encodeURIComponent(
      `Cordial saludo,\n\n` +
      `Compartimos el informe consolidado de las empresas asociadas a ${r.providerName}.\n\n` +
      `Empresas: ${r.totals.companiesCount} (${r.totals.sitesCount} sede(s))\n` +
      `Horas ejecutadas: ${r.totals.used} h de ${r.totals.assigned} h asignadas\n` +
      `Avance: ${r.totals.avancePct === null ? '—' : r.totals.avancePct + '%'}\n` +
      `Valor pagado: ${money(r.totals.paidValue)}\n` +
      `Valor pendiente por cobrar: ${money(r.totals.owedValue)}\n` +
      `Saldo disponible consolidado: ${r.totals.remaining} h\n\n` +
      `Adjunto el informe completo en PDF/Word exportado desde la plataforma.\n\n` +
      `Cordialmente,\nYasbleidis López Rhenals`
    );
    window.location.href = `mailto:?subject=${subject}&body=${body}`;
    return;
  }
  if (r.scope === 'invoice') {
    const subject = encodeURIComponent(`Cuenta de cobro SG-SST – ${r.providerName} – ${r.m}`);
    const body = encodeURIComponent(
      `Cordial saludo,\n\n` +
      `Adjunto la cuenta de cobro correspondiente a las actividades ejecutadas para ${r.providerName} durante el periodo ${r.periodLabel}.\n\n` +
      `Total actividades: ${money(r.actTotal)}\n` +
      `Total desplazamiento y representación: ${money(r.expTotal)}\n` +
      `TOTAL A COBRAR: ${money(r.grandTotal)}\n\n` +
      `Quedo atenta a la confirmación de pago.\n\n` +
      `Cordialmente,\nYasbleidis López Rhenals`
    );
    window.location.href = `mailto:?subject=${subject}&body=${body}`;
    return;
  }
  const subject = encodeURIComponent(`Informe ${r.scope === 'global' ? 'global' : 'mensual'} SG-SST – ${r.s.name} – ${r.m}`);
  const body = encodeURIComponent(
    `Cordial saludo,\n\n` +
    `Compartimos el informe ${r.scope === 'global' ? 'global consolidado' : 'mensual'} de seguimiento para ${r.c.name}, sede ${r.s.name}.\n\n` +
    `Horas ${r.scope === 'global' ? 'totales' : 'del mes'}: ${r.used} h\n` +
    `Valor ejecutado: ${money(r.executed)}\n` +
    `Valor pagado: ${money(r.paidValue)} (${r.paidCount} registro(s))\n` +
    `Valor pendiente por cobrar: ${money(r.owedValue)} (${r.owedCount} registro(s))\n` +
    `Saldo disponible en bolsa de ${r.m}: ${r.bag.remaining} h\n\n` +
    `Adjunto el informe completo en PDF/Word exportado desde la plataforma.\n\n` +
    `Cordialmente,\nYasbleidis López Rhenals`
  );
  window.location.href = `mailto:?subject=${subject}&body=${body}`;
}

// jsPDF/html2canvas no logran dibujar emojis de forma confiable (el motor de
// texto de jsPDF los codifica mal y salen como símbolos ilegibles tipo
// "Ø=Ü..."). Los emojis son solo decorativos en el informe, así que para la
// exportación a PDF se quitan de una copia temporal del contenido; en
// pantalla y en el Word sí se conservan normalmente.
function stripEmojiForPdf(html) {
  return html.replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{2300}-\u{23FF}\u{2190}-\u{21FF}\u{FE0F}]\s?/gu, '');
}

// Genera el PDF renderizando el informe a un solo canvas de alta resolución
// y cortándolo nosotros mismos en páginas, en vez de usar doc.html(...) con
// autoPaging (que fue la causa de los fondos negros). Cada recorte se pinta
// primero con blanco sólido y RECIÉN DESPUÉS se dibuja el contenido encima,
// así que no puede quedar ningún pixel transparente — por eso es seguro
// comprimir a JPEG (mucho más liviano que PNG para este tipo de contenido,
// probado: ~40 veces menos peso con la misma calidad visual) sin correr el
// riesgo original de que la transparencia se pintara negra.
// Nombre base del archivo exportado (PDF/Word), según el tipo de informe.
// "all"/"provider"/"invoice" no tienen sede (r.s) ni empresa (r.c) — antes
// esto se asumía siempre presente y el botón de exportar quedaba roto (error
// silencioso al leer r.s.name) para el Informe por proveedor y la Cuenta de
// cobro. Centralizado aquí para que PDF y Word usen la misma lógica.
function reportFileBaseName(r) {
  if (r.scope === 'all') return `informe-general-sgsst-${r.m}`;
  if (r.scope === 'provider') return `informe-proveedor-${(r.providerName || 'proveedor').replace(/\s+/g, '_')}-${r.m}`;
  if (r.scope === 'invoice') return `cuenta-cobro-${(r.providerName || 'proveedor').replace(/\s+/g, '_')}-${r.m}`;
  return `informe-sgsst-${r.s.name.replace(/\s+/g, '_')}-${r.m}`;
}

async function exportReportPDF() {
  const r = await ensureReport();
  if (!r) return;
  const el = $('reportBox');
  if (!el) return;
  if (typeof html2canvas === 'undefined' || !window.jspdf) { toast('No se pudo cargar el generador de PDF. Recarga la página e intenta de nuevo.'); return; }
  const { jsPDF } = window.jspdf;
  const filename = `${reportFileBaseName(r)}.pdf`;
  toast('Generando PDF, un momento…');

  const originalHtml = el.innerHTML;
  el.innerHTML = stripEmojiForPdf(originalHtml);

  try {
    const canvas = await html2canvas(el, { backgroundColor: '#ffffff', scale: 2, useCORS: true });

    const doc = new jsPDF('p', 'pt', 'a4');
    const margin = 20;
    const pageWidthPt = doc.internal.pageSize.getWidth() - margin * 2;
    const pageHeightPt = doc.internal.pageSize.getHeight() - margin * 2;
    // Cuántos px del canvas (a la resolución "scale" que usamos) caben en
    // el alto útil de una página, manteniendo la misma proporción con la
    // que se va a dibujar el ancho completo.
    const pxPerPt = canvas.width / pageWidthPt;
    const pageHeightPx = Math.floor(pageHeightPt * pxPerPt);

    let y = 0, first = true;
    while (y < canvas.height) {
      const sliceHeightPx = Math.min(pageHeightPx, canvas.height - y);
      const slice = document.createElement('canvas');
      slice.width = canvas.width;
      slice.height = sliceHeightPx;
      const ctx = slice.getContext('2d');
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, slice.width, slice.height);
      ctx.drawImage(canvas, 0, y, canvas.width, sliceHeightPx, 0, 0, canvas.width, sliceHeightPx);

      const sliceHeightPt = sliceHeightPx / pxPerPt;
      if (!first) doc.addPage();
      doc.addImage(slice.toDataURL('image/jpeg', 0.92), 'JPEG', margin, margin, pageWidthPt, sliceHeightPt);
      first = false;
      y += sliceHeightPx;
    }

    doc.save(filename);
  } catch (e) {
    toast('No se pudo generar el PDF: ' + e.message);
  } finally {
    el.innerHTML = originalHtml;
  }
}

// Exporta el informe a un documento de Word (.doc) editable, en lugar de
// Excel: usa el mismo contenido del informe en pantalla, con estilos en
// línea compatibles con Word, para que sea fácil de retocar antes de
// enviarlo (títulos, tablas y colores de estado se conservan).
async function exportReportWord() {
  const r = await ensureReport();
  if (!r) return;
  const el = $('reportBox');
  if (!el) return;
  const styles = `
    body{font-family:Calibri,Arial,sans-serif;color:#1f2937;font-size:11pt}
    h1,h2{color:#0B2D5B}
    h1{font-size:18pt;text-align:center}
    h2{font-size:16pt}
    table{border-collapse:collapse;width:100%;margin:10px 0}
    th,td{border:1px solid #d8e0e8;padding:6px 8px;font-size:10pt;text-align:left;vertical-align:top}
    th{background:#edf4f8}
    .badge{padding:3px 8px;border-radius:10px;font-weight:bold;font-size:9pt}
    .done{background:#e9f8ef;color:#17733c}
    .progress{background:#fff6db;color:#9a6700}
    .pending{background:#fdecec;color:#b62d2d}
    .paid{background:#e5f5ec;color:#21714f}
    .unpaid{background:#fff3dc;color:#986514}
    .small{font-size:9.5pt;color:#6b7280}
    .reportKpiCard,.reportMiniCard,.reportStatCard{border:1px solid #d8e0e8;padding:10px;margin-bottom:10px}
    .reportSectionTitle{color:#0B2D5B;font-weight:bold;font-size:12pt;margin:16px 0 8px}
    .reportInfoBox .lbl{color:#6b7280;font-weight:bold}
    .reportInfoBox .val{color:#1f2937;font-weight:bold}
    .invoiceHeader{border-bottom:3px solid #0B2D5B;padding-bottom:10px;margin-bottom:14px}
    .invoiceNumber{font-size:11pt;color:#0B2D5B;font-weight:bold}
    .invoiceMetaLine{font-size:9pt;color:#6b7280}
    .invoiceTitle{font-size:18pt;color:#0B2D5B;font-weight:bold;text-align:center}
    .invoiceConcept{background:#f5f7fa;border-left:3px solid #0B2D5B;padding:10px 14px;font-size:10.5pt}
    .invoiceTotalBand{background:#7B2CBF;color:#ffffff;padding:12px 16px;font-weight:bold;font-size:13pt}
    .invoiceTotalValue{font-size:14pt}
    .invoiceSignerName{text-align:center;font-weight:bold;color:#0B2D5B;font-size:11pt}
    .invoiceFooter{margin-top:20px;padding-top:8px;border-top:1px solid #d8e0e8;font-size:8.5pt;color:#6b7280}
    img{max-width:460px}
  `;
  const html = `<!DOCTYPE html><html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
    <head><meta charset="utf-8"><title>${r.title}</title><style>${styles}</style></head>
    <body>${el.innerHTML}</body></html>`;
  const blob = new Blob(['\ufeff', html], { type: 'application/msword' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `${reportFileBaseName(r)}.doc`;
  a.click();
  URL.revokeObjectURL(a.href);
}
